insert into products(category_id,title,brand,price,old_price,stock,badge,short,description,specs,colors,model3d,images,featured) values ((select id from categories where slug='elektromobil'),'Sport elektromobil, 2 kishilik','BabyCheer',4600000,0,5,'Yangi','Karbon uslubidagi sport dizayn, LED yoritish va spoyler.','Sport avtomobil uslubidagi 2 kishilik elektromobil: karbon tolaga o''xshash kapot, katta orqa spoyler, keng g''ildirak kamarlari, LED faralar va pastki LED yoritish. Salonda xavfsizlik kamarlari, qizil sport rul va musiqa paneli bor.','{"O''rindiq":"2 ta (yonma-yon)","Xavfsizlik":"Xavfsizlik kamarlari","Yoritish":"LED fara va pastki yoritish","Qo''shimcha":"Orqa spoyler, musiqa paneli","Kafolat":"6 oy"}'::jsonb,'[{"name":"Metallik kulrang","hex":"#6f7f86"}]'::jsonb,'',array['img/products/sport-1.jpg','img/products/sport-4.jpg','img/products/sport-3.jpg','img/products/sport-2.jpg']::text[],true);
insert into products(category_id,title,brand,price,old_price,stock,badge,short,description,specs,colors,model3d,images,featured) values ((select id from categories where slug='elektromobil'),'1 kishilik elektromobil','BabyCheer',2450000,2790000,14,'Eng ommabop','Pult, LED chiroq va musiqa. 2 yoshdan.','Pult bilan boshqariladigan, ikki rejimli (bola o''zi haydaydi yoki ota-ona pult bilan boshqaradi) bolalar elektromobili. Xavfsizlik kamari, yumshoq o''rindiq, LED chiroqlar va Bluetooth orqali musiqa.','{"Yosh":"2-6 yosh","Batareya":"12V 7Ah","Tezlik":"3-5 km/soat","Yuk ko''tarish":"30 kg gacha","Boshqaruv":"Pedal va ota-ona pulti","Kafolat":"6 oy"}'::jsonb,'[{"name":"Ko''k","hex":"#2b59ff"},{"name":"Qizil","hex":"#e5262b"},{"name":"Oq","hex":"#eef0f4"},{"name":"Qora","hex":"#1b1d24"},{"name":"Yashil","hex":"#12a66b"},{"name":"Pushti","hex":"#f0589f"}]'::jsonb,'single',array[]::text[],true);
insert into products(category_id,title,brand,price,old_price,stock,badge,short,description,specs,colors,model3d,images,featured) values ((select id from categories where slug='elektromobil'),'2 kishilik elektromobil','BabyCheer',3950000,0,8,'Yangi','Ikki o''rindiq, 4 motor, Bluetooth.','Ikki bola uchun keng salon, to''rt motorli yuritma va ota-ona pulti. Notekis yo''llarda ham barqaror: amortizatsiyali g''ildiraklar va kuchli konstruksiya.','{"Yosh":"3-8 yosh","Batareya":"24V 10Ah","Tezlik":"3-7 km/soat","Yuk ko''tarish":"60 kg gacha","Motor":"4 ta","Kafolat":"6 oy"}'::jsonb,'[{"name":"Qizil","hex":"#e5262b"},{"name":"Ko''k","hex":"#2b59ff"},{"name":"Oq","hex":"#eef0f4"},{"name":"Qora","hex":"#1b1d24"},{"name":"Sariq","hex":"#f5b800"}]'::jsonb,'double',array[]::text[],true);
insert into products(category_id,title,brand,price,old_price,stock,badge,short,description,specs,colors,model3d,images,featured) values ((select id from categories where slug='elektromobil'),'Jip uslubidagi elektromobil','BabyCheer',3290000,3690000,6,'Chegirma','Katta g''ildirak, bagajli tom, 2 o''rindiq.','Katta g''ildirakli jip: tomda bagaj, orqada zaxira g''ildirak va yuqori yo''l tirqishi. Hovli va parkda sayr qilish uchun.','{"Yosh":"3-7 yosh","Batareya":"12V 10Ah","Tezlik":"3-6 km/soat","Yuk ko''tarish":"40 kg gacha","Kafolat":"6 oy"}'::jsonb,'[{"name":"Yashil","hex":"#12a66b"},{"name":"Qora","hex":"#1b1d24"},{"name":"Oq","hex":"#eef0f4"},{"name":"To''q sariq","hex":"#ff7a1a"}]'::jsonb,'suv',array[]::text[],true);
